				"status": "In Progress",
				"priority": 5,
				"checkbox": "__YES__",
				"related_tasks": ["26ab1f9f-4c5f-80b1-8d3b-d10a6b1d2f4e"],
				"date:deadline:start": "2024-12-25",
				"date:deadline:is_datetime": 0,
